import{z as l,x as o,o as A,c as p,q as t,j as s,D as E,d as e,s as B,S as i,b as r}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"生成树","description":"","frontmatter":{"title":"生成树","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/spanning-tree.md","filePath":"cs/spanning-tree.md","lastUpdated":1791413859000}'),d={name:"cs/spanning-tree.md"};function D(m,a,P,c,h,T){const n=o("Mermaid");return A(),p("div",null,[a[2]||(a[2]=t('<h1 id="生成树" tabindex="-1">生成树 <a class="header-anchor" href="#生成树" aria-label="Permalink to &quot;生成树&quot;">​</a></h1><div class="epigraph"><p>冗余链路形成环时，广播与未知单播会绕圈放大；生成树先关掉一些端口，留下无环转发拓扑。</p><footer>—— 据 Perlman, An Algorithm for Distributed Computation of a Spanning Tree in an Extended LAN, 1985；IEEE 802.1D 整理</footer></div><p><a href="/cs/vlan">上一课</a>让交换机对未知帧泛洪。两条交换机之间若有两条链路，泛洪帧会永转，MAC 表抖动。缺口不是再学一遍源地址，而是在链路层算一棵<strong>生成树</strong>，阻塞冗余端口。图算法课的<a href="/cs/mst-kruskal-prim">最小生成树</a>给过边权树；这里权是桥优先级与端口代价，目标先是无环连通。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>物理环提供容错，逻辑必须无环。Perlman 的分布式算法：选根桥，每桥选根端口，每网段选指定端口，其余阻塞。BPDU 在桥之间交换。缺口是这套选举，不是 IP 的最短路径——生成树甚至不优化应用延迟，只保证二层可泛洪。</p><p>本课不把 RSTP 的握手时序写到状态机每一行。</p><p><span class="marginnote">数字实例：两台交换机之间拉两根千兆链路，生成树会阻塞其中一根的转发。看起来「丢了一半带宽」，但不阻塞时一帧广播会被无限复制打满两根链路、整机瘫掉——丢 50% 可用带宽，换的是剩下 50% 真能用。</span></p><p><span class="marginnote">阻塞端口仍听 BPDU，以便根失败时恢复。数据平面不转发，控制平面活着。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>比较桥 ID（优先级 + MAC）最小者为根。根代价沿 BPDU 传播。指定端口是该网段上根代价最好的桥的端口。收敛期间端口可处于学习/监听，避免临时环。VLAN 可每 VLAN 一棵树（PVST 等），主干只要求：有环必须先成树再按上一课转发。</p><p><span class="marginnote">术语翻译：根端口就是「我这台交换机去往根桥最近的那扇门」；指定端口则是「这个网段上负责替大家转发帧的那扇门」。每个非根桥恰有一个根端口，每个网段恰有一个指定端口，两样都不是的端口阻塞。</span></p>',11)),(A(),s(i,null,{default:E(()=>[B(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20RING%5B%22%E5%86%97%E4%BD%99%E9%93%BE%E8%B7%AF%22%5D%20--%3E%20BPDU%5B%22%E4%BA%A4%E6%8D%A2%20BPDU%22%5D%0A%20%20BPDU%20--%3E%20ROOT%5B%22%E9%80%89%E6%A0%B9%22%5D%0A%20%20ROOT%20--%3E%20BLK%5B%22%E9%98%BB%E5%A1%9E%E9%9D%9E%E6%A0%91%E7%AB%AF%E5%8F%A3%22%5D%0A%20%20BLK%20--%3E%20FWD%5B%22%E6%97%A0%E7%8E%AF%E6%B3%9B%E6%B4%AA%E4%B8%8E%E5%AD%A6%E4%B9%A0%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[e("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,[e("生成树把二层以太网限制成树，于是"),r("a",{href:"/cs/csma-switch"},"交换机"),e("的泛洪有终止。代价是：有的链路闲置，带宽浪费；根附近成为瓶颈。这正是后课要用三层路由、等价多路径的动机之一，本课不提前 BGP。与端到端：树断了会黑一阵，主机 TCP 自己重传——下层「几乎连通」仍不是文件保证。")],-1)),(A(),s(i,null,{default:E(()=>[B(n,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20FR%5B%22%E6%9C%AA%E7%9F%A5%E5%B8%A7%E8%BF%9B%E5%85%A5%E6%9C%89%E7%8E%AF%E6%8B%93%E6%89%91%22%5D%20--%3E%20F1%5B%22%E4%BA%A4%E6%8D%A2%E6%9C%BA%20A%20%E6%B3%9B%E6%B4%AA%22%5D%0A%20%20F1%20--%3E%20F2%5B%22%E4%BA%A4%E6%8D%A2%E6%9C%BA%20B%20%E6%94%B6%E5%88%B0%E5%86%8D%E6%B3%9B%E6%B4%AA%22%5D%0A%20%20F2%20--%3E%20F3%5B%22%E5%B8%A7%E7%BB%8F%E5%8F%A6%E4%B8%80%E6%9D%A1%E9%93%BE%E8%B7%AF%E7%BB%95%E5%9B%9E%20A%22%5D%0A%20%20F3%20--%3E%20LOOP%5B%22%E5%B8%A7%E6%97%A0%E9%99%90%E5%A4%8D%E5%88%B6%EF%BC%8C%E5%B9%BF%E6%92%AD%E9%A3%8E%E6%9A%B4%22%5D%0A%20%20STP%5B%22%E7%94%9F%E6%88%90%E6%A0%91%E9%98%BB%E5%A1%9E%E4%B8%80%E4%B8%AA%E5%8F%A3%22%5D%20--%3E%20CUT%5B%22%E7%8E%AF%E8%B7%AF%E8%A2%AB%E5%89%AA%E6%96%AD%22%5D%0A%20%20CUT%20--%3E%20STOP%5B%22%E6%B3%9B%E6%B4%AA%E6%9C%89%E7%BB%88%E6%AD%A2%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p>这张图回答的是：不阻塞冗余端口时广播帧如何沿环自我复制——风暴不是「流量大」，而是每一份拷贝又生出拷贝，所以必须在拓扑层剪环。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 TRILL、SPB、EVPN 当默认校园网，不引入最短路径二层的全部控制平面。也不把生成树根劫持写成攻击步骤。无线 mesh 与有线桥不是同一算法。</p><p>根桥选举若被更小优先级抢占，树会 reconverge，转发暂停。优先级是管理配置，不是 MAC 自动最优。</p><p>RSTP 用提议/同意加速，对象仍是一棵无环活动拓扑。</p><p><span class="marginnote">常见误区：初学者容易以为阻塞端口「死了」。实际上它一直在听 BPDU——根桥或活动链路一失效，它在数十秒内（RSTP 快得多）切换成转发。数据面歇着，控制面醒着，这正是「物理环当备份、逻辑树管转发」的分工。</span></p><p>后课默认：同一广播域在树上看是无环的。跨网还缺「哪一跳的 MAC 对应哪个 IP」，下一课 ARP。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>二层环 + 泛洪 = 风暴；生成树阻塞冗余。</li><li>选根、根端口、指定端口；BPDU 传播。</li><li>IP 与 ARP 还没有：下一课在已连通的链路上解析地址。</li><li>出处：Perlman, 1985；IEEE 802.1D；Kurose and Ross。</li></ul>',9))])}const _=l(d,[["render",D]]);export{u as __pageData,_ as default};
